async function openSeal(t,key){try{const [p,s]=t.split(".");if(!p||s!==await mac(p,key))return null;const o=JSON.parse(new TextDecoder().decode(un64(p)));return o.exp>Date.now()?o:null}catch{return null}}
function cookie(req,n){return (req.headers.get("Cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith(n+"="))?.slice(n.length+1)||""}
function cookieSet(n,v,age){return n+"="+v+"; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age="+age}
