async function callback(req,env,u){const state=u.searchParams.get("state")||"",saved=cookie(req,STATE),code=u.searchParams.get("code");if(!state||state!==saved||!code)return new Response("OAuth state 驗證失敗，請重新登入。",{status:400});const tr=await fetch("https://github.com/login/oauth/access_token",{method:"POST",headers:{Accept:"application/json","Content-Type":"application/json"},body:JSON.stringify({client_id:env.GITHUB_CLIENT_ID,client_secret:env.GITHUB_CLIENT_SECRET,code})});const td=await tr.json();if(!td.access_token)return new Response("GitHub OAuth 登入失敗。",{status:401});const ur=await fetch("https://api.github.com/user",{headers:{Authorization:"Bearer "+td.access_token,Accept:"application/vnd.github+json","User-Agent":"611-portfolio-admin"}});const user=await ur.json();if((user.login||"").toLowerCase()!==ALLOWED.toLowerCase())return new Response("此 GitHub 帳號沒有管理權限。",{status:403,headers:{"Set-Cookie":clear(STATE)}});const session=await seal({login:user.login,exp:Date.now()+8*3600000},env.SESSION_SECRET);const h=new Headers({Location:"/admin","Cache-Control":"no-store"});h.append("Set-Cookie",cookieSet(COOKIE,session,28800));h.append("Set-Cookie",clear(STATE));return new Response(null,{status:302,headers:h})}
async function auth(req,env){const s=await openSeal(cookie(req,COOKIE),env.SESSION_SECRET);return s?.login?.toLowerCase()===ALLOWED.toLowerCase()?s:null}
