 const drawList=(target,items,mobile)=>{const list=$(target);list.replaceChildren();const ordered=items.slice().sort((a,b)=>a.order-b.order);ordered.forEach((item,i)=>{const row=document.createElement("div");row.className="item";const name=document.createElement("strong");name.textContent=(i+1)+". "+(homeLabels[item.id]||item.id);const toggle=document.createElement("label");toggle.style.margin="0";toggle.style.display="flex";toggle.style.alignItems="center";toggle.style.gap="6px";const check=document.createElement("input");check.type="checkbox";check.style.width="auto";check.checked=item.visible!==false;check.onchange=()=>{item.visible=check.checked};toggle.append(check,document.createTextNode("顯示"));const up=document.createElement("button");up.className="secondary";up.textContent="上移";up.disabled=i===0;up.onclick=()=>homeMove(i,-1,mobile);const down=document.createElement("button");down.className="secondary";down.textContent="下移";down.disabled=i===ordered.length-1;down.onclick=()=>homeMove(i,1,mobile);const actions=document.createElement("span");actions.append(toggle,up,down);row.append(name,actions);list.append(row)})};
